 const sources='<section class="bz-health-chapter"><div class="bz-health-chapter-head"><span>07 / '+esc(t('ANTES DE VIAJAR','ANTES DE VIAJAR','BEFORE YOU GO'))+'</span><h2>'+esc(t('Seguro, documentos y fuentes oficiales','Seguro, documentos e fontes oficiais','Insurance, documents and official sources'))+'</h2><p>'+esc(t('Los turistas extranjeros pueden solicitar atención de urgencia en el SUS. Conserva pasaporte o documento, lista de medicación y alergias, datos del seguro y contacto de emergencia. La asistencia pública no sustituye el seguro de viaje para todas las situaciones.','Turistas estrangeiros podem procurar urgência no SUS. Leve passaporte ou documento, lista de remédios e alergias, seguro e contato de emergência. O atendimento público não substitui seguro viagem em todas as situações.','Foreign visitors can seek emergency care through the public SUS. Keep ID or passport, medication and allergy details, insurance details and an emergency contact. Public services do not replace travel insurance for every situation.'))+'</p></div><figure class="bz-health-topic-photo bz-health-insurance-photo"><img src="https://mediumturquoise-stinkbug-270478.hostingersite.com/FOTOS/HOME/GUIA%20DE%20RIO/SEGURO%20Y%20SALUD/ABAJO%20PORTADA%20SEGURO%20Y%20SALUD.jpg" alt="'+esc(t('Preparación de la asistencia y el seguro de viaje','Preparação da assistência e do seguro viagem','Preparing travel insurance and medical assistance'))+'" loading="lazy" decoding="async"></figure><div class="bz-health-resources"><a href="https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/saude-do-viajante/durante-sua-estadia/durante-sua-estadia/" target="_blank" rel="noopener noreferrer">'+esc(t('Ministerio de Salud · viajeros ↗','Ministério da Saúde · viajantes ↗','Health Ministry · visitors ↗'))+'</a><a href="https://www.gov.br/saude/pt-br/composicao/saes/samu-192" target="_blank" rel="noopener noreferrer">SAMU 192 ↗</a><a href="https://cnes2.datasus.gov.br/Mod_Conjunto.asp?VCo_Unidade=3300236200702" target="_blank" rel="noopener noreferrer">CNES · Hospital ↗</a><a href="https://cnes2.datasus.gov.br/Mod_Ambulatorial.asp?VCo_Unidade=3300232271540" target="_blank" rel="noopener noreferrer">CNES · Rasa ↗</a>'+related+'</div></section>';
