function renderTransportMatrix(data,lang){
 if(!data)return '';
 const headers=data.columns.map(c=>'<th scope="col">'+esc(value(c,lang))+'</th>').join('');
 const rows=data.rows.map(row=>'<tr>'+row.map((cell,i)=>'<td data-label="'+esc(value(data.columns[i],lang))+'">'+esc(value(cell,lang))+'</td>').join('')+'</tr>').join('');
 const title=esc(value(data.title,lang));
 return '<section class="bz-section bz-transport-data"><div class="bz-wrap"><div class="bz-section-head"><h2>'+title+'</h2><p>'+esc(value(data.caption,lang))+'</p></div><div class="bz-table-scroll" role="region" aria-label="'+title+'" tabindex="0"><table><thead><tr>'+headers+'</tr></thead><tbody>'+rows+'</tbody></table></div></div></section>';
}
