 const imageAlt=[T('Microbús local de Cooper Búzios','Micro-ônibus local da Cooper Búzios','Cooper Búzios local minibus'),T('Aplicación Uber en un teléfono dentro de un vehículo','Aplicativo Uber em um celular dentro de um veículo','Uber app on a phone inside a vehicle'),T('Recepción de pasajeros junto a un automóvil de traslado','Recepção de passageiros ao lado de um carro de transfer','Passengers welcomed beside a transfer car'),T('Entrega de llaves para alquilar un automóvil','Entrega das chaves para alugar um carro','Car rental key handover'),T('Embarcaciones en Praia da Armação, Búzios','Embarcações na Praia da Armação, Búzios','Boats at Praia da Armação, Búzios')];
 const icons=['🚌','🚕','🚐','🚘','⛵'];
 return '<section class="bz-transport-clone" id="bz-transport-options"><div class="tgrid">'+slugs.map((slug,i)=>'<article class="tcard"><img class="transport-thumb" src="'+pictures[i]+'" alt="'+esc(imageAlt[i][lang])+'" loading="lazy"><div class="transport-content"><span class="transport-index-number">'+String(i+1).padStart(2,'0')+'</span><i aria-hidden="true">'+icons[i]+'</i><h2>'+esc(value(names[i],lang))+'</h2><strong>'+esc(value(desc[i],lang))+'</strong><p>'+esc(value(desc[i],lang))+'</p><a class="detail-link" href="'+esc(localizedHref(root+slug+'/',lang))+'">'+esc(T('Abrir guía completa','Abrir guia completo','Read full guide')[lang])+' →</a></div></article>').join('')+'</div></section>';
